document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)act(b.dataset.action)});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.field){const f=el.dataset.field;if(f==='text'){if(active())active().text=el.value;state.exportData=null;state.exportReady=false;state.draft=true;}else if(f==='query'){state.query=el.value;const start=el.selectionStart;const holder=document.createElement('div');holder.innerHTML=search();$('#search-results').innerHTML=holder.querySelector('#search-results').innerHTML;el.focus();if(el.type!=='search')el.setSelectionRange(start,start)}else if(f==='lesson'){lesson=el.value;render()}else if(['brightness','contrast'].includes(f)){state[f]=Number(el.value);if(active())active()[f]=state[f];$('#'+f+'-value').textContent=el.value+'%';document.querySelectorAll('.scan-preview .paper').forEach(p=>p.style.filter=imageStyle(active()));state.exportData=null;state.exportReady=false;state.ocrReady=false;state.draft=true;}else{state[f]=el.value;if(f==='title'){state.draft=true;state.exportReady=false;state.exportData=null}}save();}if(el.dataset.pair!==undefined){state.captures[Number(el.dataset.pair)].pairLabel=el.value;state.pairConfirmed=false;invalidateExport()}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.setting){state.settings[el.dataset.setting]=el.type==='checkbox'?el.checked:el.value;save()}if(el.dataset.side!==undefined){state.captures[Number(el.dataset.side)].side=el.value;state.pairConfirmed=false;invalidateExport();render(true)}if(el.id==='file-input'){
 const files=[...el.files].slice(0,12);if(!files.length||busy)return;
 const token=++job;busy=true;const accepted=[];
 sheet('Importing images',`<p>Preparing images locally. Your existing pages stay unchanged until this finishes.</p>${btn('Cancel','cancel-job',false,'close')}`);
 for(const file of files){
  if(token!==job)return;
  if(!file.type.startsWith('image/')||file.size>8*1024*1024)continue;
  const data=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>resolve(null);r.readAsDataURL(file)});
  if(token!==job)return;if(!data)continue;
  const valid=await new Promise(resolve=>{const image=new Image();const timeout=setTimeout(()=>resolve(false),4000);image.onload=()=>{clearTimeout(timeout);resolve(image.naturalWidth>0&&image.naturalHeight>0)};image.onerror=()=>{clearTimeout(timeout);resolve(false)};image.src=data;});
  if(token!==job)return;if(!valid)continue;
  const kind=state.mode==='cards'?'card':'document';const index=state.captures.length+accepted.length;
  const side=kind==='card'&&state.workflow==='paired'?(index%2?'Back':'Front'):'Single';
  accepted.push({...makeRegion(kind,side),label:`${kind==='card'?'Card':'Page'} ${index+1}`,image:data});
 }
 if(token!==job)return;busy=false;closeSheet();
 if(!accepted.length){notify('No readable images imported. Use image files smaller than 8 MB.');return}
 state.active=state.captures.length;state.captures.push(...accepted);state.pairConfirmed=false;invalidate();nav('04');
 notify(`${accepted.length} image${accepted.length===1?'':'s'} imported. OCR remains simulated.`);
}});

function validCorners(points){if(!points||points.length!==4)return false;const cross=points.map((a,i)=>{const b=points[(i+1)%4],c=points[(i+2)%4];return(b[0]-a[0])*(c[1]-b[1])-(b[1]-a[1])*(c[0]-b[0])});return cross.every(n=>n>8)||cross.every(n=>n< -8)}
function setupCorners(){const canvas=$('#crop-canvas');if(!canvas)return;const move=(i,x,y)=>{active().corners[i]=[Math.max(2,Math.min(98,x)),Math.max(2,Math.min(98,y))];const b=canvas.querySelector(`[data-corner="${i}"]`);b.style.left=active().corners[i][0]+'%';b.style.top=active().corners[i][1]+'%';$('#crop-polygon').setAttribute('points',active().corners.map(p=>p.join(',')).join(' '));state.exportData=null;state.exportReady=false;state.ocrReady=false;state.draft=true;save()};canvas.querySelectorAll('[data-corner]').forEach(b=>{const i=Number(b.dataset.corner);b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);const drag=ev=>{const r=canvas.getBoundingClientRect();move(i,(ev.clientX-r.left)/r.width*100,(ev.clientY-r.top)/r.height*100)};b.addEventListener('pointermove',drag);b.addEventListener('pointerup',()=>b.removeEventListener('pointermove',drag),{once:true});b.addEventListener('pointercancel',()=>b.removeEventListener('pointermove',drag),{once:true})});b.addEventListener('keydown',e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();const p=active().corners[i];move(i,p[0]+(e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0),p[1]+(e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0))})})}
if(new URLSearchParams(location.search).get('sample')==='cards'&&route==='07'){
 state.mode='cards';state.captures=[makeRegion('card','Front'),makeRegion('card','Back')];state.captures.forEach(r=>r.pairLabel='Studio card');state.active=0;
}
// Read-only inspection supports deterministic local design verification, not an API service.
window.__design={get state(){return structuredClone(state)},get route(){return route}};
render();
